from copying import clone

def merge(defaults, overrides):
    result = clone(defaults)
    for key, override_value in overrides.items():
        if override_value is not None:
            if isinstance(result.get(key), dict) and isinstance(override_value, dict):
                result[key] = merge(result[key], override_value)
            elif isinstance(result.get(key), list) and isinstance(override_value, list):
                result[key] = result[key] + override_value
            elif isinstance(result.get(key), type(None)) and isinstance(override_value, type(None)):
                result[key] = None
            else:
                result[key] = override_value
    return result

